-- Roles are created by the local compose initializer; this file is safe to reapply after ACL-free restore.
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'ofertasuper_runtime') THEN CREATE ROLE ofertasuper_runtime NOLOGIN; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'ofertasuper_authority') THEN CREATE ROLE ofertasuper_authority NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'ofertasuper_verifier') THEN CREATE ROLE ofertasuper_verifier LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'ofertasuper_verifier_definer') THEN CREATE ROLE ofertasuper_verifier_definer NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; END IF; END $$;
REVOKE ALL ON DATABASE ofertasuper FROM PUBLIC;
GRANT CONNECT ON DATABASE ofertasuper TO ofertasuper_app, ofertasuper_runtime, ofertasuper_authority;
REVOKE ofertasuper_owner FROM ofertasuper_app, ofertasuper_runtime, ofertasuper_authority;
REVOKE ofertasuper_authority FROM ofertasuper_app, ofertasuper_runtime;
ALTER ROLE ofertasuper_app NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
ALTER ROLE ofertasuper_runtime NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
REVOKE CREATE ON SCHEMA public FROM PUBLIC, ofertasuper_app, ofertasuper_runtime;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC, ofertasuper_app, ofertasuper_runtime;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM PUBLIC, ofertasuper_app, ofertasuper_runtime;
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC, ofertasuper_app, ofertasuper_runtime;
GRANT USAGE ON SCHEMA public TO ofertasuper_app, ofertasuper_runtime;
