ALTER SEQUENCE public.supermarket_products_id_seq OWNER TO ofertasuper_owner;
ALTER SEQUENCE public.price_history_id_seq OWNER TO ofertasuper_owner;
ALTER SEQUENCE public.promotions_id_seq OWNER TO ofertasuper_owner;
ALTER SEQUENCE public.categories_id_seq OWNER TO ofertasuper_owner;
ALTER SEQUENCE public.ingestion_run_id_seq OWNER TO ofertasuper_owner;
ALTER SEQUENCE public.staging_product_id_seq OWNER TO ofertasuper_owner;
ALTER SEQUENCE public.source_health_id_seq OWNER TO ofertasuper_owner;
