REVOKE EXECUTE ON FUNCTION public.create_approval_challenge(text,text,text,text,text,text,text,timestamptz,timestamptz), public.consume_approval_challenge(text), public.record_candidate_approval_receipt(text,text,text,timestamptz,text), public.prepare_authority_revoke_consent(jsonb), public.record_authority_revoke_consent(jsonb) FROM PUBLIC, ofertasuper_app, ofertasuper_runtime, ofertasuper_verifier;
GRANT EXECUTE ON FUNCTION public.create_approval_challenge(text,text,text,text,text,text,text,timestamptz,timestamptz), public.consume_approval_challenge(text), public.record_candidate_approval_receipt(text,text,text,timestamptz,text), public.prepare_authority_revoke_consent(jsonb), public.record_authority_revoke_consent(jsonb) TO ofertasuper_authority;
GRANT SELECT ON TABLE public.governed_catalogs, public.serving_products, public.serving_supermarkets, public.serving_offers, public.serving_history, public.serving_promotions, public.serving_memberships TO ofertasuper_runtime;
ALTER DEFAULT PRIVILEGES FOR ROLE ofertasuper_owner REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
ALTER DEFAULT PRIVILEGES FOR ROLE ofertasuper_owner IN SCHEMA public REVOKE ALL ON TABLES FROM PUBLIC, ofertasuper_app;
ALTER DEFAULT PRIVILEGES FOR ROLE ofertasuper_owner IN SCHEMA public REVOKE ALL ON SEQUENCES FROM PUBLIC, ofertasuper_app;
ALTER DEFAULT PRIVILEGES FOR ROLE ofertasuper_owner IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC, ofertasuper_app;
ALTER ROLE "ofertasuper_verifier" LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
ALTER ROLE "ofertasuper_verifier_definer" NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
GRANT CONNECT ON DATABASE "ofertasuper" TO "ofertasuper_verifier";
REVOKE "ofertasuper_owner" FROM "ofertasuper_verifier";
REVOKE "ofertasuper_verifier" FROM "ofertasuper_app", "ofertasuper_runtime";
REVOKE "ofertasuper_app", "ofertasuper_runtime" FROM "ofertasuper_verifier";
REVOKE CREATE ON SCHEMA "public" FROM "ofertasuper_verifier";
REVOKE ALL ON ALL TABLES IN SCHEMA "public" FROM "ofertasuper_verifier";
REVOKE ALL ON ALL SEQUENCES IN SCHEMA "public" FROM "ofertasuper_verifier";
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA "public" FROM "ofertasuper_verifier";
GRANT USAGE ON SCHEMA "public" TO "ofertasuper_verifier";
GRANT SELECT ON TABLE "public"."products", "public"."supermarkets", "public"."supermarket_products", "public"."price_history", "public"."promotions", "public"."promotion_products", "public"."categories", "public"."ingestion_run", "public"."staging_product", "public"."source_health", "public"."direct_refresh_run_ledger", "public"."governed_catalogs", "public"."catalog_operations", "public"."serving_products", "public"."serving_supermarkets", "public"."serving_offers", "public"."serving_history", "public"."serving_promotions", "public"."serving_memberships", "public"."production_readiness_promotions", "public"."production_readiness_receipts", "public"."production_readiness_publications", "public"."source_capture_operations", "public"."source_capture_items", "public"."delta_verifications", "public"."evidence_artifacts", "public"."evidence_references", "public"."evidence_dependencies", "public"."evidence_restrictions" TO "ofertasuper_verifier";
-- "public"."commit_promotion_ready_envelope"(bytea, text) and future "public"."admit_promotion_ready_envelopes"(jsonb) use session_user as caller provenance; current_user is the definer and not caller provenance.
DO $verifier_acl$ DECLARE target regprocedure; BEGIN FOREACH target IN ARRAY ARRAY[pg_catalog.to_regprocedure('public.commit_promotion_ready_envelope(bytea,text)'), pg_catalog.to_regprocedure('public.admit_promotion_ready_envelopes(jsonb)')] LOOP IF target IS NOT NULL THEN IF NOT (SELECT p.prosecdef AND p.proconfig = ARRAY['search_path=pg_catalog, pg_temp'] FROM pg_catalog.pg_proc p WHERE p.oid = target) THEN RAISE EXCEPTION 'unsafe verifier boundary'; END IF; EXECUTE pg_catalog.format('ALTER FUNCTION %s OWNER TO "ofertasuper_verifier_definer"', target); EXECUTE pg_catalog.format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC, "ofertasuper_app", "ofertasuper_runtime"', target); EXECUTE pg_catalog.format('GRANT EXECUTE ON FUNCTION %s TO "ofertasuper_verifier"', target); END IF; END LOOP; IF pg_catalog.to_regprocedure('public.canonical_json_text(jsonb)') IS NOT NULL THEN EXECUTE 'ALTER FUNCTION "public"."canonical_json_text"(jsonb) OWNER TO "ofertasuper_verifier_definer"'; EXECUTE 'REVOKE EXECUTE ON FUNCTION "public"."canonical_json_text"(jsonb) FROM PUBLIC, "ofertasuper_app", "ofertasuper_runtime", "ofertasuper_verifier"'; END IF; IF pg_catalog.to_regprocedure('public.envelope_items_ordered(jsonb)') IS NOT NULL THEN EXECUTE 'ALTER FUNCTION "public"."envelope_items_ordered"(jsonb) OWNER TO "ofertasuper_verifier_definer"'; EXECUTE 'REVOKE EXECUTE ON FUNCTION "public"."envelope_items_ordered"(jsonb) FROM PUBLIC, "ofertasuper_app", "ofertasuper_runtime", "ofertasuper_verifier"'; END IF; END $verifier_acl$;
